// data/kit.json is generated by `npm run kit` from genshin-db plus data/kit-overrides.json (#68, #73).
import { expect, test } from "vitest";
import kit from "../../../data/kit.json";
import overrides from "../../../data/kit-overrides.json";
import tags from "../../../data/tags.json";

type KitEntry = { buffs: { value: number; uptime: number | null }[]; missing?: string };
const characters = kit.characters as Record<string, KitEntry>;

test("every tagged buffer has a kit entry with readable values", () => {
  const buffers = tags.filter((c) => c.roles.includes("buffer") && (c.buffs ?? []).length > 0).map((c) => c.id);
  // Plus a kit bonus to the team's reaction damage from a non-buffer (Kaveh's Painted Dome, #256).
  expect(Object.keys(characters).sort()).toEqual([...buffers, "Kaveh"].sort());
  for (const [id, c] of Object.entries(characters)) {
    if (c.missing) continue;
    expect(c.buffs.length, id).toBeGreaterThan(0);
    for (const b of c.buffs) {
      expect(b.value, id).toBeGreaterThan(0);
      if (b.uptime !== null) expect(b.uptime, id).toBeLessThanOrEqual(1);
    }
  }
});

// Mavuika's Fighting Spirit (#116): every other Nightsoul member gives her a sourced number of points per rotation.
test("every Nightsoul member has sourced Fighting Spirit points", () => {
  const fs = (kit as unknown as { fightingSpirit: { limit: number; burstMin: number; own: { points: number }; teammates: Record<string, { points: number; source: string }> } }).fightingSpirit;
  expect([fs.limit, fs.burstMin, fs.own.points]).toEqual([200, 100, 80]);
  const nightsoul = tags.filter((c) => (c.families ?? []).includes("nightsoul") && c.id !== "Mavuika").map((c) => c.id);
  expect(Object.keys(fs.teammates).sort()).toEqual(nightsoul.sort());
  for (const [id, t] of Object.entries(fs.teammates)) {
    expect(t.points, id).toBeGreaterThan(0);
    expect(t.source, id).toMatch(/\S/);
  }
});

// Each Moonsign Benediction raises the party's Moonsign by 1 level, which is how ascendantGleamLines counts
// it: so every Moonsign family member must have one, and nobody else.
test("the Moonsign family is exactly the characters with a Moonsign Benediction", { timeout: 60_000 }, async () => {
  const genshindb = (await import("genshin-db")).default;
  const withBenediction = tags
    .filter((c) => {
      const t = genshindb.talents(c.id);
      return [t?.passive1, t?.passive2, t?.passive3, t?.passive4].some((p) => p?.name.startsWith("Moonsign Benediction"));
    })
    .map((c) => c.id);
  const family = tags.filter((c) => (c.families ?? []).includes("moonsign")).map((c) => c.id);
  expect(family.sort()).toEqual(withBenediction.sort());
});

// Lunar and Stellar conversion comes from each character's "Moonsign Benediction" / "Stellar Jubilee"
// passive (#63): tags.json's `converts` must say exactly what that sentence converts into.
test("converts matches the conversion sentence in genshin-db's kit text", { timeout: 60_000 }, async () => {
  const genshindb = (await import("genshin-db")).default;
  const OUTPUTS: Record<string, string> = {
    "Lunar-Charged": "lunar-charged",
    "Lunar-Bloom": "lunar-bloom",
    "Lunar-Crystallize": "lunar-crystallize",
    "Stellar-Conduct": "stellar-conduct",
    "Stellar Swirl": "stellar-swirl",
  };
  const fromKit: Record<string, string[]> = {};
  for (const c of tags) {
    const t = genshindb.talents(c.id);
    for (const p of [t?.passive1, t?.passive2, t?.passive3, t?.passive4]) {
      if (!p || !/^(Moonsign Benediction|Stellar Jubilee)/.test(p.name)) continue;
      const sentence = p.description.replace(/\s+/g, " ").split(/(?<=\.) /).find((s) => /converted into|becomes a|changed to/.test(s));
      const out = sentence ? Object.keys(OUTPUTS).filter((n) => sentence.includes(n)).map((n) => OUTPUTS[n]) : [];
      if (out.length > 0) fromKit[c.id] = out;
    }
  }
  const fromTags = Object.fromEntries(tags.filter((c) => "converts" in c).map((c) => [c.id, (c as { converts: string[] }).converts]));
  expect(fromTags).toEqual(fromKit);
});

// Sub-DPS hits (#95): every off-field sub-DPS has an entry, each source has a multiplier, a rate and a cooldown.
type SubDpsSource = { label: string; scaling: Record<string, number>; hits?: number; every?: number; duration?: number; cd: number };
const subDps = (kit as unknown as { subDps: Record<string, { sources: SubDpsSource[]; missing?: string[] }> }).subDps;

test("every off-field sub-DPS has hit data with a multiplier, a rate and a cooldown", () => {
  const offField = tags.filter((c) => c.roles.includes("sub-dps") && c.fieldTime === "off").map((c) => c.id);
  // Supports whose in-game roles aren't DPS (#105) may have entries too: their hits still deal damage.
  for (const id of offField) expect(subDps, id).toHaveProperty([id]);
  for (const [id, d] of Object.entries(subDps)) {
    expect(d.sources.length, id).toBeGreaterThan(0);
    for (const s of d.sources) {
      expect(Object.values(s.scaling).every((v) => v > 0) && Object.keys(s.scaling).length > 0, `${id} ${s.label}`).toBe(true);
      expect((s.hits ?? 0) > 0 || ((s.every ?? 0) > 0 && (s.duration ?? 0) > 0), `${id} ${s.label}: hits or every + duration`).toBe(true);
      expect(s.cd, `${id} ${s.label}`).toBeGreaterThan(0);
    }
  }
});

test("talent table labels are read per stat, hit and multiple (#95)", () => {
  const source = (id: string, label: string) => subDps[id].sources.find((s) => s.label === label)!;
  expect(Object.keys(source("Chiori", "Tamoto DMG").scaling).sort()).toEqual(["atk", "def"]); // "{p} ATK+{q} DEF"
  expect(source("Xingqiu", "Skill DMG").scaling.atk).toBeCloseTo(2.856 + 3.2504, 4); // "{p}+{q}": two hits
  expect(source("Yelan", "Exquisite Throw DMG").scaling.hp).toBeCloseTo(0.082824 * 3, 6); // "... Max HP ×3"
});

test("sub-DPS passives that add damage from EM are read into their hits (#172)", () => {
  const source = (id: string, label: string) => subDps[id].sources.find((s) => s.label === label)! as SubDpsSource & {
    dmgBonusPerStat?: Record<string, number>;
  };
  expect(source("Citlali", "Frostfall Storm DMG").scaling.em).toBe(0.9); // passive 2: +90% of EM
  expect(source("Citlali", "Ice Storm DMG").scaling.em).toBe(12); // passive 2: +1200% of EM
  expect(source("Aino", "Water Ball DMG").scaling.em).toBe(0.5); // passive 2: Burst DMG +50% of EM
  expect(source("Traveler (Dendro)", "Skill DMG").dmgBonusPerStat).toEqual({ em: 0.0015 }); // +0.15% DMG per EM
  expect(source("Traveler (Dendro)", "Lea Lotus Lamp Attack DMG").dmgBonusPerStat).toEqual({ em: 0.001 }); // +0.1%
});

for (const [id, d] of Object.entries(subDps)) {
  for (const m of d.missing ?? []) test.todo(`kit-overrides hitRates: ${id} ${m}`);
}

// data/kit-overrides.json fills what genshin-db is missing (#73). The shape is checked here; each slot that is
// still empty shows as a todo, so `npm test` lists what is left to copy from the game.

const TALENT_KEYS = /^(combat[1-3]|passive[1-4]|c[1-6])$/;
type Slot = { talent: string; name: string; text: string; source: string };

test("kit-overrides.json slots name a known character and talent, with a source once filled", () => {
  const ids = new Set(tags.map((c) => c.id));
  for (const [id, c] of Object.entries(overrides.characters as Record<string, { why: string; slots: Slot[] }>)) {
    expect(ids.has(id), `${id} is not in tags.json`).toBe(true);
    for (const s of c.slots) {
      if (!s.text.trim()) continue;
      expect(s.talent, `${id}: a filled slot needs its talent`).toMatch(TALENT_KEYS);
      expect(s.source.trim(), `${id} ${s.talent}: say where the text came from`).not.toBe("");
    }
  }
});

for (const [id, c] of Object.entries(overrides.characters as Record<string, { why: string; slots: Slot[] }>)) {
  for (const s of c.slots.filter((s) => !s.text.trim())) test.todo(`kit-overrides: ${id} ${s.talent || "(which talent?)"}: ${c.why}`);
}
if (!overrides.rules.nightsoulBurst.whoCanTrigger.trim()) test.todo("kit-overrides: rules.nightsoulBurst: who can trigger it");

// Reaction bonuses to a transformative reaction's own damage (#256): Nilou's only in an all-Dendro/Hydro team, Kaveh's
// only while he is the on-field carry, Baizhu's per 1,000 Max HP.
test("reactionBonusesFor reads the team's kit bonuses to reaction damage (#256)", async () => {
  const { reactionBonusesFor } = await import("./kit");
  const { loadScoringCharacters } = await import("./load");
  const all = loadScoringCharacters();
  const team = (...ids: string[]) => ids.map((id) => all.find((c) => c.id === id)!);
  const nilou = team("Kaveh", "Nilou", "Yelan", "Furina");
  // Nilou at the 35,000 HP buffer benchmark: 9% x 5 = 45%; Kaveh's 46.7% at 12s of 20s.
  expect(reactionBonusesFor("bloom", nilou[0], nilou).bonus).toBeCloseTo(0.45 + 0.467296 * 0.6, 4);
  expect(reactionBonusesFor("bloom", nilou[1], nilou).bonus).toBeCloseTo(0.45, 4); // Kaveh off field
  const mixed = team("Kaveh", "Nilou", "Bennett", "Furina"); // Pyro breaks Nilou's condition
  expect(reactionBonusesFor("bloom", mixed[0], mixed).bonus).toBeCloseTo(0.467296 * 0.6, 4);
  expect(reactionBonusesFor("hyperbloom", nilou[0], nilou).bonus).toBe(0);
  const lauma = team("Nahida", "Lauma", "Xingqiu", "Kuki Shinobu");
  expect(reactionBonusesFor("hyperbloom", lauma[0], lauma).additive).toBeGreaterThan(0); // flat from her EM
});
